const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define regions: Northern Kenya (Turkana) and Southern Kenya (Tsavo)
  const northernKenya = ee.Geometry.Point([35.2, 3.5]);
  const southernKenya = ee.Geometry.Point([38.5, -3.0]);

  const buffer = 50000; // 50 km buffer for region
  const northGeom = northernKenya.buffer(buffer);
  const southGeom = southernKenya.buffer(buffer);

  const startDate = '2019-05-01';
  const endDate = '2019-06-30';

  // Function to compute NDVI and statistics
  async function getNDVIStats(geometry, regionName) {
    let collection = ee.ImageCollection('COPERNICUS/S2')
      .filterDate(startDate, endDate)
      .filterBounds(geometry)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

    const colSize = await collection.size().getInfo();

    if (colSize === 0) {
      console.log(`${regionName} Images: 0`);
      return null;
    }

    // Cloud masking function
    const maskClouds = (image) => {
      const qa = image.select('QA60');
      const cloudBitMask = 1 << 10;
      const cirrusBitMask = 1 << 11;
      const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
      return image.updateMask(mask).divide(10000);
    };

    // Apply cloud mask and calculate NDVI
    const ndviCollection = collection.map((img) => {
      const masked = maskClouds(img);
      const ndvi = masked.normalizedDifference(['B8', 'B4']).rename('NDVI');
      return ndvi;
    });

    // Check if any valid pixels exist
    const pixelCount = ndviCollection.first()
      .reduceRegion(
        ee.Reducer.count(),
        geometry,
        30,
        null,
        null,
        false,
        1e9
      )
      .get('NDVI')
      .getInfo();

    if (pixelCount === 0) {
      console.log(`${regionName} Valid Pixels: 0`);
      return null;
    }

    // Calculate mean NDVI
    const meanNDVI = ndviCollection.mean()
      .reduceRegion(
        ee.Reducer.mean(),
        geometry,
        30,
        null,
        null,
        false,
        1e9
      )
      .get('NDVI')
      .getInfo();

    console.log(`${regionName} Images: ${colSize}, Valid Pixels: ${pixelCount}, Mean NDVI: ${meanNDVI.toFixed(4)}`);
    return meanNDVI;
  }

  // Get NDVI for both regions
  const northNDVI = await getNDVIStats(northGeom, 'Northern Kenya');
  const southNDVI = await getNDVIStats(southGeom, 'Southern Kenya');

  // Validate results
  if (northNDVI === null || southNDVI === null) {
    if (northNDVI === null && southNDVI === null) {
      console.log('No valid pixels in both regions after masking.');
      console.log('C2');
    } else {
      console.log('One or both regions lack valid data.');
      console.log('C2');
    }
    return;
  }

  if (isNaN(northNDVI) || isNaN(southNDVI)) {
    console.log('NDVI calculation resulted in NaN.');
    console.log('C3');
    return;
  }

  // Compare NDVI values
  console.log(`Comparison: Northern NDVI (${northNDVI.toFixed(4)}) vs Southern NDVI (${southNDVI.toFixed(4)})`);

  if (northNDVI < southNDVI) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
